def compute(vars):
    americas_revenue = vars["v1"]
    total_revenue = vars["v2"]

    if total_revenue == 0:
        return None

    percentage = americas_revenue / total_revenue * 100

    return {
        "value": percentage,
        "trace": {
            "americas_revenue": americas_revenue,
            "total_revenue": total_revenue,
            "percentage": percentage,
            "output_meta": {
                "currency": None,
                "scale": "percent",
                "unit": "percentage"
            }
        }
    }
